static List<String> normalizeTags(List<String> tags) {
    tags.replaceAll(t -> t.trim().toLowerCase());
    tags.sort(null);
    for (int i = tags.size() - 1; i > 0; i--) {
        if (tags.get(i).equals(tags.get(i - 1))) tags.remove(i);
    }
    return tags;
}

